"use client";

import { CheckIcon, CopyIcon } from "@phosphor-icons/react";
import * as React from "react";

import { Button } from "@/components/ui/button";
import { useCopyToClipboard } from "@/hooks/use-copy-to-clipboard";
import { cn } from "@/lib/utils";

type CopyButtonProps = Omit<React.ComponentProps<typeof Button>, "onClick" | "value"> & {
  /** Names what is being copied, e.g. "setup key" renders "Copy setup key". */
  label: string;
  value: string;
};

function CopyButton({
  children,
  label,
  size = "icon-xs",
  value,
  variant = "ghost",
  ...props
}: CopyButtonProps) {
  const { copy, status } = useCopyToClipboard();
  // Button padding only tightens for an icon that sits beside content.
  const iconPlacement = children ? "inline-end" : undefined;

  return (
    <>
      <Button
        aria-label={
          status === "copied"
            ? `${label} copied`
            : status === "error"
              ? `Copy ${label} failed. Try again`
              : `Copy ${label}`
        }
        data-slot="copy-button"
        onClick={() => void copy(value)}
        size={size}
        type="button"
        variant={variant}
        {...props}
      >
        {children}
        {status === "copied" ? (
          <CheckIcon className="text-status-success" data-icon={iconPlacement} weight="bold" />
        ) : (
          <CopyIcon
            className={cn("text-muted-foreground", status === "error" && "text-destructive")}
            data-icon={iconPlacement}
          />
        )}
      </Button>
      <span aria-live="polite" className="sr-only" role="status">
        {status === "copied"
          ? `${label} copied to clipboard.`
          : status === "error"
            ? `${label} could not be copied. Try again.`
            : ""}
      </span>
    </>
  );
}

export { CopyButton };

import { useCallback, useEffect, useRef, useState } from "react";

export type CopyStatus = "copied" | "error" | "idle";

export function useCopyToClipboard({ resetAfter = 1600 }: { resetAfter?: number } = {}) {
  const [status, setStatus] = useState<CopyStatus>("idle");
  const timer = useRef<number | null>(null);

  const clearTimer = useCallback(() => {
    if (timer.current !== null) {
      window.clearTimeout(timer.current);
      timer.current = null;
    }
  }, []);

  useEffect(() => clearTimer, [clearTimer]);

  const copy = useCallback(
    async (value: string) => {
      clearTimer();
      let copied = true;
      try {
        if (!navigator.clipboard?.writeText) {
          throw new Error("Clipboard access is unavailable.");
        }
        await navigator.clipboard.writeText(value);
      } catch {
        copied = false;
      }

      setStatus(copied ? "copied" : "error");
      timer.current = window.setTimeout(() => {
        setStatus("idle");
        timer.current = null;
      }, resetAfter);
      return copied;
    },
    [clearTimer, resetAfter],
  );

  return { copy, status };
}
